CREATE TABLE IF NOT EXISTS "public"."friendships" (
    "user_a_id" "uuid" NOT NULL,
    "user_b_id" "uuid" NOT NULL,
    "requested_by" "uuid" NOT NULL,
    "status" "public"."friendship_status" DEFAULT 'pending'::"public"."friendship_status" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "responded_at" timestamp with time zone,
    CONSTRAINT "friendships_check" CHECK (("user_a_id" < "user_b_id")),
    CONSTRAINT "friendships_check1" CHECK ((("requested_by" = "user_a_id") OR ("requested_by" = "user_b_id")))
);


ALTER TABLE "public"."friendships" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."location_pings" (
    "ping_id" bigint NOT NULL,
    "session_id" "uuid" NOT NULL,
    "user_id" "uuid" NOT NULL,
    "recorded_at" timestamp with time zone NOT NULL,
    "location" "public"."geography"(Point,4326) NOT NULL,
    "altitude_m" numeric(7,2),
    "accuracy_m" numeric(6,2),
    "speed_mps" numeric(5,2),
    "heading_deg" numeric(5,1),
    CONSTRAINT "location_pings_heading_deg_check" CHECK ((("heading_deg" >= (0)::numeric) AND ("heading_deg" < (360)::numeric)))
)
PARTITION BY RANGE ("recorded_at");


ALTER TABLE "public"."location_pings" OWNER TO "postgres";


