CREATE TABLE IF NOT EXISTS "public"."ride_metrics" (
    "session_id" "uuid" NOT NULL,
    "user_id" "uuid" NOT NULL,
    "distance_m" integer DEFAULT 0 NOT NULL,
    "moving_time_s" integer DEFAULT 0 NOT NULL,
    "elapsed_time_s" integer DEFAULT 0 NOT NULL,
    "avg_speed_mps" numeric(5,2),
    "max_speed_mps" numeric(5,2),
    "elevation_gain_m" integer,
    "route_completion_pct" numeric(5,2),
    "recorded_path" "public"."geography"(LineString,4326),
    "computed_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "ride_metrics_route_completion_pct_check" CHECK ((("route_completion_pct" >= (0)::numeric) AND ("route_completion_pct" <= (100)::numeric)))
);


ALTER TABLE "public"."ride_metrics" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."ride_sessions" (
    "session_id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "host_id" "uuid" NOT NULL,
    "route_id" "uuid",
    "title" character varying(120) NOT NULL,
    "description" "text",
    "status" "public"."session_status" DEFAULT 'scheduled'::"public"."session_status" NOT NULL,
    "visibility" "public"."session_visibility" DEFAULT 'private'::"public"."session_visibility" NOT NULL,
    "max_participants" smallint DEFAULT 20,
    "meetup_location" "public"."geography"(Point,4326),
    "is_no_drop" boolean DEFAULT true NOT NULL,
    "scheduled_start" timestamp with time zone,
    "started_at" timestamp with time zone,
    "ended_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "ride_sessions_check" CHECK ((("ended_at" IS NULL) OR ("started_at" IS NULL) OR ("ended_at" >= "started_at"))),
    CONSTRAINT "ride_sessions_max_participants_check" CHECK (("max_participants" > 0))
);


ALTER TABLE "public"."ride_sessions" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."routes" (
    "route_id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "created_by" "uuid" NOT NULL,
    "name" character varying(120) NOT NULL,
    "description" "text",
    "path" "public"."geography"(LineString,4326) NOT NULL,
    "start_point" "public"."geography"(Point,4326) NOT NULL,
    "end_point" "public"."geography"(Point,4326) NOT NULL,
    "is_loop" boolean DEFAULT false NOT NULL,
    "distance_m" integer NOT NULL,
    "est_duration_s" integer,
    "times_ridden" integer DEFAULT 0 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "deleted_at" timestamp with time zone,
    CONSTRAINT "routes_distance_m_check" CHECK (("distance_m" > 0)),
    CONSTRAINT "routes_est_duration_s_check" CHECK (("est_duration_s" > 0)),
    CONSTRAINT "routes_times_ridden_check" CHECK (("times_ridden" >= 0))
);


ALTER TABLE "public"."routes" OWNER TO "postgres";


